questionvariables.text:
/* Randomize radius r in metres, range [1.0, 2.0), to 1 decimal place */
r: (rand(10) + 10) / 10;

/* Randomize angle theta in degrees, range [25, 85] */
theta_deg: rand(60) + 25;

/* Fraction of full turn swept */
theta_frac: theta_deg / 360;

/* Use pi = 22/7 as specified in the question */
pi_val: 22/7;

r_square: r^2;

/* Area of the sector: A = (theta/360) * pi * r^2 */
area: theta_frac * pi_val * r_square;
Area: float(decimalplaces(area, 2));

/* Distractor: mistake of using arc length formula instead of sector area */
area_arclength_mistake: theta_frac * 2 * pi_val * r;
Area_arclength_mistake: float(decimalplaces(area_arclength_mistake, 2));
